 const [shoppingDraft,setShoppingDraft]=useState<ShoppingDraft>(emptyShoppingDraft);const shoppingAttemptId=useRef<string|null>(null);const [checkComposing,setCheckComposing]=useState(false);const updateDraft=useRef({editor:false,checklist:false,shopping:false,composing:false});const updateBlocked=Boolean(edit)||Boolean(checkText.trim())||Boolean(shoppingDraft.id||shoppingDraft.place.trim()||shoppingDraft.item.trim())||checkComposing||saving;const updates=useAppUpdates(updateBlocked,()=>updateDraft.current.editor||updateDraft.current.checklist||updateDraft.current.shopping||updateDraft.current.composing||access.current.saving);
 function changeCheckText(value:string){updateDraft.current.checklist=Boolean(value.trim());setCheckText(value);}
 const viewStarted=useRef(0);useEffect(()=>{if(viewStarted.current)recordViewPaint(view,viewStarted.current)},[view]);
 const shell=useRef<HTMLDivElement>(null);const priorViews=useRef<{view:View,day:string,scroll:number}[]>([]);const pendingScroll=useRef<number|null>(null);const [navigationTick,setNavigationTick]=useState(0);
 function navigationBlocked(){return updateDraft.current.editor||updateDraft.current.composing||access.current.saving||Boolean(document.querySelector('dialog[open]'));}
 function setView(next:View){viewStarted.current=performance.now();if(updateDraft.current.editor||updateDraft.current.composing||document.querySelector('dialog[open]'))return;priorViews.current=[];if(next===view)return;pendingScroll.current=0;setViewState(next);setNavigationTick(n=>n+1);}
 function openDetail(next:View){viewStarted.current=performance.now();if(next===view||navigationBlocked())return;priorViews.current.push({view,day,scroll:window.scrollY});if(priorViews.current.length>12)priorViews.current.shift();pendingScroll.current=0;setViewState(next);setNavigationTick(n=>n+1);}
