 useEdgeBack(shell,()=>!navigationBlocked(),previousView);
 useEffect(()=>{if(pendingScroll.current===null)return;const top=pendingScroll.current;pendingScroll.current=null;const frame=requestAnimationFrame(()=>window.scrollTo({top,behavior:'auto'}));return()=>cancelAnimationFrame(frame)},[navigationTick]);const motionView=useRef(view);useEffect(()=>{if(motionView.current===view)return;motionView.current=view;enterView(document.querySelector('.main-panel'))},[view]);
