 useEffect(()=>{void import('./place-search').catch(()=>{});void load(true);setAppleMobile(isAppleMobile(navigator.userAgent,navigator.platform,navigator.maxTouchPoints));return()=>{loadEpoch.current++;access.current.fresh=false;}},[]);
 useEffect(()=>{if(edit)dialog.current?.showModal();else dialog.current?.close()},[edit?.kind]);
 useEffect(()=>{if(!isDialogOpen)return;const viewport=window.visualViewport;const root=dialog.current;const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const update=()=>{root?.style.setProperty('--visible-height',`${viewport?.height||window.innerHeight}px`);root?.style.setProperty('--visible-top',`${viewport?.offsetTop||0}px`);};update();viewport?.addEventListener('resize',update);viewport?.addEventListener('scroll',update);window.addEventListener('resize',update);return()=>{viewport?.removeEventListener('resize',update);viewport?.removeEventListener('scroll',update);window.removeEventListener('resize',update);document.body.style.overflow=previousOverflow;};},[isDialogOpen]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(id)},[toast]);
 async function save(next:Trip,message='저장했어요'){if(!snap||!access.current.fresh||access.current.loading||access.current.saving)return false;access.current.saving=true;const generation=cacheGeneration();setSaving(true);setError('');try{const r=await fetch('/api/trip',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({trip:next,version:snap.version})});const data=await responseData(r);if(!r.ok){setConflict(r.status===409);if(r.status===409){access.current.fresh=false;setFresh(false);}throw new Error(data.error||'저장하지 못했어요');}if(!validSnapshot(data))throw Error('저장 결과를 확인하지 못했어요. 다시 불러와주세요');setSnap(data);cacheTrip(data,generation);setCheckedAt(Date.now());setToast(message);return true;}catch(e){setError(e instanceof TypeError?'연결이 끊겼어요. 입력 내용은 유지되어 있으니 다시 저장해주세요':e instanceof Error?e.message:'연결이 끊겼어요. 입력 내용은 유지되어 있으니 다시 저장해주세요');return false;}finally{access.current.saving=false;setSaving(false);}}
 function changeShoppingDraft(next:ShoppingDraft){if(!next.id&&!next.place&&!next.item)shoppingAttemptId.current=null;updateDraft.current.shopping=Boolean(next.id||next.place.trim()||next.item.trim());setShoppingDraft(next);}
 function editShoppingItem(item:ShoppingItem){if(shoppingDraft.id===item.id)return true;if(updateDraft.current.shopping&&shoppingDraft.id!==item.id&&!window.confirm('작성 중인 쇼핑 항목을 닫고 이 항목을 수정할까요?'))return false;changeShoppingDraft({id:item.id,place:item.place,item:item.item,base:{...item}});return true;}
 async function saveShoppingDraft(){if(!trip||locked||updateDraft.current.composing)return;const item=shoppingDraft.item.trim();if(!item)return;const list=trip.shopping||[];const itemId=shoppingDraft.id||(shoppingAttemptId.current??=crypto.randomUUID());const existing=list.find(x=>x.id===itemId);if(!existing&&list.length>=200){setError('쇼핑목록은 최대200개까지 저장할 수 있어요');return;}if(!shoppingDraft.id&&existing&&existing.place===shoppingDraft.place.trim()&&existing.item===item){changeShoppingDraft(emptyShoppingDraft);setToast('쇼핑목록에 저장됐어요');return;}if((shoppingDraft.id||existing)&&JSON.stringify(existing)!==JSON.stringify(shoppingDraft.base)&&!window.confirm(existing?'다른 기기에서 이 물품도 수정했어요. 지금 입력한 장소·물품으로 바꿀까요?':'다른 기기에서 이 물품을 삭제했어요. 지금 입력한 내용으로 다시 만들까요?'))return;const next:ShoppingItem={id:itemId,place:shoppingDraft.place.trim(),item,done:existing?.done??false};const shopping=existing?list.map(x=>x.id===next.id?next:x):[...list,next];if(await save({...trip,shopping},shoppingDraft.id?'쇼핑 항목을 수정했어요':'쇼핑목록에 추가했어요'))changeShoppingDraft(emptyShoppingDraft);}
 async function toggleShoppingItem(id:string){if(!trip||locked)return;const current=(trip.shopping||[]).find(x=>x.id===id);if(!current)return;await save({...trip,shopping:(trip.shopping||[]).map(x=>x.id===id?{...x,done:!x.done}:x)},current.done?'구매 전으로 바꿨어요':'구매 완료로 표시했어요');}
