 function mapDetails(r:Recommendation){const target=mapTarget(r.id);const uncertain=!target||['unverified','official_only'].includes(target.status);const label=uncertain?'지도 지점 확인 필요':target.status==='building'?'건물 위치 · 매장 층 확인':target.status==='official_identifier'?'공식 지도 · 도보 경로 미확인':'매장·지도 상세';return <details className={`map-details ${uncertain?'map-uncertain':''}`}><summary>{label}</summary><p><strong>주소</strong> {r.address}</p><p>{r.why}</p><p>{target?.note||'공식 안내에서 지점을 확인해주세요'}</p>{isMonterey&&r.walking?.timeLabel&&<p>{r.walking.note}</p>}<p>{r.needsConfirmation}</p>{target?.sourceURL&&target.sourceURL!==r.sourceURL&&<a href={target.sourceURL} target="_blank" rel="noopener noreferrer">지도 출처 <ArrowUpRight size={11}/></a>}</details>;}
 const entries=trip?sortedEntries(trip.entries.filter(x=>x.day===day)):[];const places=savedPlaces(trip?.entries||[]);const completed=trip?.checks.filter(x=>x.done).length||0;const numChecks=trip?.checks.length||0;
